function icon(name, cls='') { return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.grid}</svg>`; }
const villages = [
 {id:'karsog',name:'Karsog',area:'Mandi district · Himachal Pradesh',risk:86,level:'CRITICAL',rain:68,moisture:88,slope:37,pop:'8,420',lead:'32 min',x:250,y:160,color:'#bf424b',type:'Flash flood + landslide'},
 {id:'thunag',name:'Thunag',area:'Mandi district · Himachal Pradesh',risk:74,level:'VERY HIGH',rain:54,moisture:79,slope:42,pop:'5,680',lead:'48 min',x:376,y:112,color:'#df7d3b',type:'Landslide'},
 {id:'janjehli',name:'Janjehli',area:'Mandi district · Himachal Pradesh',risk:69,level:'HIGH',rain:48,moisture:72,slope:34,pop:'4,210',lead:'1 hr 06 min',x:483,y:205,color:'#e58c40',type:'Landslide'},
 {id:'sundernagar',name:'Sundernagar',area:'Mandi district · Himachal Pradesh',risk:57,level:'HIGH',rain:41,moisture:68,slope:26,pop:'12,900',lead:'1 hr 24 min',x:220,y:278,color:'#e58c40',type:'Flash flood'},
 {id:'aut',name:'Aut',area:'Mandi district · Himachal Pradesh',risk:43,level:'MODERATE',rain:29,moisture:58,slope:24,pop:'3,160',lead:'2 hr 10 min',x:492,y:316,color:'#d3ac3e',type:'Watch'},
 {id:'gohar',name:'Gohar',area:'Mandi district · Himachal Pradesh',risk:31,level:'MODERATE',rain:22,moisture:46,slope:19,pop:'6,730',lead:'3 hr 05 min',x:622,y:256,color:'#c5a73e',type:'Watch'},
 {id:'pandoh',name:'Pandoh',area:'Mandi district · Himachal Pradesh',risk:22,level:'LOW',rain:16,moisture:35,slope:16,pop:'2,840',lead:'—',x:662,y:140,color:'#55a97e',type:'Low'}
];
let state={view:'command',drawer:null,modal:null,location:villages[0],simRain:68,simMoisture:78,updated:new Date()};
const navItems=[
 {section:'Monitor',items:[['command','Command center','grid'],['risk-map','Hyper-local risk map','map'],['alerts','Early warnings','bell','4'],['incidents','Incident reports','flag','3']]},
 {section:'Response',items:[['evacuation','Evacuation & shelters','route'],['resources','Emergency resources','truck'],['citizen','Citizen view','users']]},
 {section:'Intelligence',items:[['analytics','Analytics & reports','activity'],['history','Historical disasters','clock'],['simulation','Scenario simulation','trend']]},
 {section:'System',items:[['data-health','Data health','wifi'],['model','Model monitoring','database'],['settings','System settings','settings']]}
];
function navHTML(){return navItems.map(g=>`<div class="nav-section">${g.section}</div>${g.items.map(([id,label,ic,b])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}" aria-label="${label}">${icon(ic)}<span>${label}</span>${b?`<b class="nav-badge">${b}</b>`:''}</button>`).join('')}`).join('');}
function shell(content){return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('mountain')}</div><div class="brand-copy">Aegis Terrain<small>Early warning network</small></div></div><nav class="nav-scroll" aria-label="Primary navigation">${navHTML()}</nav><div class="sidebar-footer"><div class="connection"><span class="dot"></span><div><b>All systems operational</b>Last sync 2 min ago</div></div><div class="user-mini"><div class="avatar">RP</div><div><strong>Riya Pradhan</strong><small>District operator</small></div><button class="icon-button collapse" title="Sign out" data-action="logout">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><strong class="topbar-title">Aegis Terrain</strong><div class="search">${icon('search')}<input id="global-search" type="search" placeholder="Search villages, wards or alerts" aria-label="Search" /></div><div class="topbar-spacer"></div><span class="system-pill"><span class="dot"></span>Systems nominal</span><span class="topbar-time" id="topbar-time"></span><button class="icon-button topbar-action" data-action="notifications" title="Notifications">${icon('bell')}<span class="notification-dot"></span></button><button class="avatar" data-action="profile" title="Open profile">RP</button></header><div class="content">${content}</div></main></div>`;}
function pageHeader(eyebrow,title,subtitle,actions=''){return `<div class="page-header"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="header-actions">${actions}</div></div>`;}
function tag(level){return `<span class="tag ${level.toLowerCase().replace(' ','-')}">${level}</span>`;}
function metricCard(label,value,unit,sub,ic,trend,risk=false){return `<article class="card metric-card ${risk?'risk-card':''}"><div class="metric-top"><div class="metric-label"><span class="metric-icon">${icon(ic)}</span>${label}</div>${risk?tag('VERY HIGH'):''}</div><div class="metric-value">${value}<span>${unit}</span></div><div class="metric-sub">${trend?`<b class="${trend[0]==='+'?'trend-up':'trend-down'}">${trend}</b>`:''}${sub}</div></article>`;}
function mapSVG(){const pins=villages.map(v=>`<g class="map-pin" data-location="${v.id}" tabindex="0" role="button" aria-label="${v.name}, ${v.level} risk"><circle class="pin-ring" cx="${v.x}" cy="${v.y}" r="9" stroke="${v.color}" opacity=".75"/><circle class="pin-dot" cx="${v.x}" cy="${v.y}" r="5" fill="${v.color}"/><text x="${v.x+12}" y="${v.y+3}">${v.name}</text></g>`).join('');return `<svg class="map-svg" viewBox="0 0 760 390" preserveAspectRatio="xMidYMid slice" aria-label="Hyper-local risk map of Mandi district"><path class="zone red" d="M176 84c57-41 133-46 188-16 29 16 40 43 79 52 44 11 92 22 112 59 19 36-6 73-42 92-35 18-65 10-96 28-47 29-122 28-164-2-26-19-28-57-62-79-33-22-57-63-39-94 6-11 13-28 24-40Z"/><path class="zone orange" d="M90 190c44-28 98-17 124 12 20 23 51 33 75 58 24 26 19 65-12 86-35 36-98 25-131 1-19-14-21-39-45-53-42-24-58-80-11-104Z"/><path class="zone yellow" d="M447 38c49-20 101-11 136 17 32 27 47 66 38 105-10 39-46 51-81 42-25-6-41-26-65-39-34-20-60-61-38-93 3-5 5-26 10-32Z"/><path class="zone green" d="M523 230c47-19 109-8 137 27 26 32 16 72-18 90-33 18-87 10-114-13-30-24-43-82-5-104Z"/><path class="river" d="M51 309c66-32 115-46 160-83 44-36 65-68 106-74 50-7 65 26 104 37 50 13 93 0 126-35 31-33 41-75 85-102"/><path class="river" d="M75 362c56-43 98-74 151-86 45-10 84 3 124 33 34 25 68 27 107 14 36-12 57-38 81-68" style="stroke-width:1.5"/><path class="road" d="M21 289c77-5 118 2 171-25 54-28 93-77 143-89 48-11 73 20 119 24 63 5 113-23 179-89"/><path class="road" d="M262 26c-4 55 23 90 63 123 38 32 83 49 90 96 6 40-8 81-27 128"/><path class="boundary" d="M111 91c67 30 121 27 173 1 48-23 96-35 154-12 39 16 61 42 108 47 52 5 99-18 147 13M70 210c64 29 124 17 167-4 51-26 79-18 112 1 40 23 66 30 103 28 51-3 91-22 137 4"/>${pins}</svg>`;}
function mapCard(full=false){return `<section class="card ${full?'map-page-card':'map-card'}"><div class="map-head"><div><h2>${full?'Live risk surface':'Hyper-local risk map'}</h2><p>Village-level conditions · Mandi district, Himachal Pradesh</p></div><select class="select"><option>Combined risk</option><option>Rainfall intensity</option><option>Landslide susceptibility</option><option>Flood exposure</option></select></div><div class="map-body">${mapSVG()}<div class="map-controls"><button data-action="zoom-in">+</button><button data-action="zoom-out">−</button><button data-action="locate">${icon('location')}</button></div><div class="map-legend"><span>Risk</span><span class="legend-item"><i class="legend-dot" style="background:#55a97e"></i>Low</span><span class="legend-item"><i class="legend-dot" style="background:#d3ac3e"></i>Moderate</span><span class="legend-item"><i class="legend-dot" style="background:#e58c40"></i>High</span><span class="legend-item"><i class="legend-dot" style="background:#bf424b"></i>Critical</span></div></div></section>`;}
function rainfallChart(){return `<svg class="chart" viewBox="0 0 420 145" preserveAspectRatio="none"><defs><linearGradient id="rain-gradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#23c4be"/><stop offset="1" stop-color="#23c4be" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 20h420M0 58h420M0 96h420M0 134h420"/><path class="chart-area" d="M0 124 42 119 84 120 126 111 168 116 210 84 252 93 294 59 336 68 378 27 420 40V145H0Z"/><path class="chart-line" d="M0 124 42 119 84 120 126 111 168 116 210 84 252 93 294 59 336 68 378 27 420 40"/><g class="chart-label"><text x="0" y="144">06:00</text><text x="75" y="144">09:00</text><text x="158" y="144">12:00</text><text x="242" y="144">15:00</text><text x="326" y="144">18:00</text><text x="391" y="144">Now</text></g><circle class="chart-point" cx="420" cy="40" r="3.5"/></svg>`;}
function soilChart(){return `<svg class="chart" viewBox="0 0 330 145" preserveAspectRatio="none"><path class="chart-grid" d="M0 22h330M0 60h330M0 98h330M0 134h330"/><path class="chart-line orange" d="M0 117 33 112 66 111 99 98 132 102 165 88 198 78 231 82 264 55 297 48 330 35"/><g class="chart-label"><text x="0" y="144">12h ago</text><text x="87" y="144">08:00</text><text x="182" y="144">14:00</text><text x="285" y="144">Now</text></g><circle class="chart-point orange" cx="330" cy="35" r="3.5"/></svg>`;}
function commandView(){return `${pageHeader('District command center · Live operations','Good morning, Riya','A decision-support view for hyper-local landslide and flash-flood risk across Mandi district.',`<button class="btn btn-quiet" data-action="refresh">${icon('refresh')}Refresh data</button><button class="btn btn-primary" data-action="generate-report">${icon('file')}Generate report</button>`)}<div class="overview-header"><div class="location-line">${icon('location')} Monitoring <b>Mandi district</b><span>·</span> 64 villages · 218 wards <select class="select"><option>Today, 23 Sep 2026</option></select></div><div class="live-updated"><span class="dot"></span>Live model run complete <span>·</span> updated 2 minutes ago</div></div><div class="metric-grid">${metricCard('Rainfall intensity','42','mm / 3h','Current accumulation','cloud','+18%')}${metricCard('Soil moisture','78','%','Saturation threshold 85%','drop','+6%')}${metricCard('High-slope exposure','31','wards','of 64 monitored','mountain','+3 wards')}${metricCard('Combined disaster risk','74','/ 100','Confidence 91% · regional median','shield','+12 pts',true)}</div><div class="alert-strip"><span class="alert-symbol">${icon('alert')}</span><div class="alert-strip-content"><strong>Priority attention · Karsog & Thunag</strong><p>Risk moved from High to Very High in the last 45 minutes. Heavy rainfall and rising soil moisture are the primary drivers.</p></div><button class="btn btn-quiet btn-sm" data-action="view-alerts">Review warning ${icon('arrow')}</button></div><div class="main-grid">${mapCard(false)}<section class="card card-pad priority-card"><div class="card-header"><div><h2>Priority locations</h2><p>Ranked by current combined risk</p></div><a class="link" href="#" data-view="risk-map">View all ${icon('arrow')}</a></div><ul class="priority-list">${villages.slice(0,5).map((v,i)=>`<li class="priority-item"><span class="rank">0${i+1}</span><div class="priority-location"><strong>${v.name}</strong><small>${v.type} · ${v.lead} lead time</small></div><div class="priority-score"><b>${v.risk}</b><small>${v.level}</small></div></li>`).join('')}</ul><button class="btn btn-quiet btn-sm" style="width:100%;margin-top:11px" data-view="risk-map">Open district risk map ${icon('arrow')}</button></section></div><div class="bottom-grid"><section class="card card-pad chart-card"><div class="card-header"><div><h2>Rainfall intensity</h2><p>Last 12 hours · Karsog reference station</p></div><span class="tag high">42 mm / 3h</span></div>${rainfallChart()}<div class="chart-legend"><span><i class="legend-line"></i>Observed rainfall</span><span>Peak 18:00 · 21 mm/hr</span></div></section><section class="card card-pad chart-card"><div class="card-header"><div><h2>Soil saturation</h2><p>Regional median · 24 hour trend</p></div><span class="tag high">Rising</span></div><div class="saturation"><div class="saturation-header"><div class="saturation-value">78<small>%</small></div><span class="trend-up">+6.4%</span></div><div class="progress"><span style="width:78%"></span></div><div class="scale"><span>Dry</span><span>Watch 65%</span><span>Saturated 85%</span></div></div>${soilChart()}</section><section class="card card-pad chart-card"><div class="card-header"><div><h2>Recommended actions</h2><p>Based on current risk engine output</p></div>${icon('info')}</div><ul class="action-list"><li>${icon('eye')} Keep Karsog control room on active watch</li><li>${icon('users')} Pre-alert 2 response teams near Thunag</li><li>${icon('route')} Inspect NH-305 and mark alternate route</li><li>${icon('shield')} Verify shelter capacity before escalation</li></ul></section></div>`;}
function riskMapView(){return `${pageHeader('Geospatial intelligence','Hyper-local risk map','Inspect village and ward-level risk, environmental drivers, and response assets.',`<button class="btn btn-quiet" data-action="layers">${icon('map')}Manage layers</button><button class="btn btn-primary" data-action="download">${icon('download')}Export map</button>`)}<div class="filter-row"><button class="filter-chip active">All risk levels</button><button class="filter-chip">Critical only</button><button class="filter-chip">Landslide zones</button><button class="filter-chip">Flood exposure</button><span class="topbar-spacer"></span><span class="muted" style="font-size:10px">7 monitored locations · refreshed 2 min ago</span></div><div class="two-col"><div>${mapCard(true)}</div><section class="card card-pad"><div class="card-header"><div><h2>Locations on map</h2><p>Click a location for its full profile</p></div><span class="tag high">3 high priority</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Location</th><th>Risk</th><th>Lead time</th></tr></thead><tbody>${villages.map(v=>`<tr data-location="${v.id}" class="clickable-row"><td><strong>${v.name}</strong><small>${v.area.split(' · ')[0]}</small></td><td>${tag(v.level)}</td><td class="mono">${v.lead}</td></tr>`).join('')}</tbody></table></div><div class="info-banner" style="margin-top:15px;margin-bottom:0">${icon('info')}<div><strong>Map layers are decision support</strong>Risk estimates use the latest validated environmental data and may change as new observations arrive.</div></div></section></div>`;}
function alertsView(){const a=[['EMERGENCY','Karsog','Flash flood probability crossed 80%. Move residents to designated shelters immediately.','86%','32 min','23 Sep · 18:22'],['WARNING','Thunag','Sustained rainfall and steep-slope saturation indicate elevated landslide risk.','74%','48 min','23 Sep · 18:08'],['WARNING','Sundernagar','River-adjacent wards under high runoff watch. Prepare local response teams.','57%','1h 24m','23 Sep · 17:51'],['WATCH','Janjehli','Rainfall forecast revised upward for the next 3 hours. Monitor trigger levels.','69%','1h 06m','23 Sep · 17:38']];return `${pageHeader('Warning operations','Early warning center','Create, review and track warnings before conditions become dangerous.',`<button class="btn btn-quiet" data-action="alert-rules">${icon('settings')}Alert rules</button><button class="btn btn-danger" data-action="new-alert">${icon('plus')}Issue warning</button>`)}<div class="kpi-grid"><div class="card kpi"><span class="kpi-label">Active alerts</span><div class="kpi-value">04</div><span class="kpi-note up">2 need acknowledgement</span></div><div class="card kpi"><span class="kpi-label">Warnings issued today</span><div class="kpi-value">12</div><span class="kpi-note">+3 vs. 7-day average</span></div><div class="card kpi"><span class="kpi-label">Average lead time</span><div class="kpi-value">54m</div><span class="kpi-note good">+11 min improvement</span></div><div class="card kpi"><span class="kpi-label">Acknowledgement rate</span><div class="kpi-value">91%</div><span class="kpi-note good">Within target · 85%</span></div></div><div class="info-banner">${icon('info')}<div><strong>Escalation policy is active</strong>Automatic alerts notify district operators first. Level 3 warnings require officer acknowledgement before citizen notifications are sent.</div></div><section class="card alert-page-card"><div class="card-header" style="padding:18px 19px 5px;margin-bottom:0"><div><h2>Active and recent warnings</h2><p>Every alert includes an estimated lead time and recommended action.</p></div><select class="select"><option>All statuses</option><option>Active only</option><option>Expired</option></select></div>${a.map(x=>`<div class="alert-row"><div class="alert-severity ${x[0]==='WATCH'?'watch':''}"><i></i>${x[0]}</div><div class="alert-main"><strong>${x[1]} · ${x[0]==='EMERGENCY'?'Flash flood':'Landslide watch'}</strong><small>${x[2]}</small></div><div class="alert-meta"><label>Probability</label>${x[3]}</div><div class="alert-meta"><label>Lead time</label><span class="lead-time">${x[4]}</span></div><div class="alert-meta"><label>Issued</label>${x[5]}</div></div>`).join('')}</section>`;}
