function simulationView(){const score=Math.min(99,Math.round(20+state.simRain*.45+state.simMoisture*.18));const level=score>=82?'CRITICAL':score>=65?'VERY HIGH':score>=48?'HIGH':'MODERATE';return `${pageHeader('Decision support','Scenario simulation','Explore how changing environmental conditions may affect risk. Simulation outputs are not official warnings.',`<button class="btn btn-quiet" data-action="reset-sim">${icon('refresh')}Reset scenario</button><button class="btn btn-primary" data-action="save-sim">${icon('file')}Save scenario</button>`)}<div class="info-banner">${icon('info')}<div><strong>What-if analysis</strong>Adjust rainfall and soil moisture to understand the combined risk engine. This does not change live data or issue alerts.</div></div><div class="two-col"><section class="card card-pad"><div class="card-header"><div><h2>Scenario inputs</h2><p>Reference location · Karsog</p></div><span class="tag high">Live baseline</span></div><div class="simulator"><div class="range-control"><label>Rainfall accumulation <b id="sim-rain-value">${state.simRain} mm / 3h</b></label><input id="sim-rain" type="range" min="0" max="160" value="${state.simRain}" /></div><div class="range-control"><label>Soil moisture <b id="sim-moisture-value">${state.simMoisture}%</b></label><input id="sim-moisture" type="range" min="10" max="100" value="${state.simMoisture}" /></div></div><div class="sim-result"><div class="sim-result-head"><b>Projected combined risk</b><span class="sim-result-value" id="sim-score">${score}<small style="font:10px Manrope;color:#9b9696"> / 100</small></span></div><div style="margin:4px 0 13px" id="sim-level">${tag(level)}</div><div class="factor-bars"><div class="factor-bar"><label>Rainfall</label><div class="progress"><span id="sim-rain-bar" style="width:${Math.min(100,state.simRain/1.6)}%;background:#e58c40"></span></div><em>${Math.round(state.simRain/1.6)}%</em></div><div class="factor-bar"><label>Soil moisture</label><div class="progress"><span id="sim-moisture-bar" style="width:${state.simMoisture}%;background:#23a9a1"></span></div><em>${state.simMoisture}%</em></div><div class="factor-bar"><label>Historical risk</label><div class="progress"><span style="width:74%;background:#8467d5"></span></div><em>74%</em></div><div class="factor-bar"><label>Slope exposure</label><div class="progress"><span style="width:71%;background:#d3aa42"></span></div><em>71%</em></div></div></div></section><section class="card card-pad"><div class="card-header"><div><h2>Projected impact</h2><p>Estimated change from current baseline</p></div>${icon('trend')}</div><ul class="stat-list"><li><span>Risk movement</span><b id="sim-movement" style="color:#ba474d">Moderate → ${level}</b></li><li><span>Likely affected wards</span><b>${score>80?'9':score>60?'6':'3'}</b></li><li><span>Estimated population</span><b>${score>80?'18,420':score>60?'12,610':'6,280'}</b></li><li><span>Lead time estimate</span><b>${score>80?'32 min':score>60?'48 min':'1 hr 24 min'}</b></li><li><span>Alert recommendation</span><b style="color:${score>80?'#bb444b':'#b47b22'}">${score>80?'EMERGENCY':score>60?'WARNING':'WATCH'}</b></li></ul><div class="insight" style="margin-top:15px"><strong>Why this changes</strong><p>Higher rainfall raises runoff and pore-water pressure. When soil moisture approaches saturation, steep-slope areas respond more quickly and available lead time decreases.</p></div></section></div>`;}
