function safetyView(){return `${pageHeader('Public safety','Safety & emergency guide','Clear, simple actions for landslides, flash floods and evacuation.',`<button class="btn btn-danger" data-action="safety-alert">${icon('alert')}Emergency mode</button>`)}<div class="citizen-grid"><section class="card safety-card"><div class="metric-label"><span class="metric-icon">${icon('mountain')}</span>Landslide safety</div><h2 style="margin-top:13px">If a slope becomes unstable</h2><ul><li>Move away from slopes, retaining walls and drainage channels.</li><li>Listen for unusual cracks, falling rocks or rumbling.</li><li>Do not cross fresh debris or attempt to drive through it.</li><li>Report blocked roads or damaged homes to local officials.</li></ul></section><section class="card safety-card"><div class="metric-label"><span class="metric-icon">${icon('drop')}</span>Flash-flood safety</div><h2 style="margin-top:13px">If water rises quickly</h2><ul><li>Move to higher ground and follow the designated route.</li><li>Never walk, swim or drive through moving water.</li><li>Stay away from riverbanks, culverts and bridges.</li><li>Keep emergency documents and medicines ready.</li></ul></section></div><section class="card card-pad" style="margin-top:16px"><div class="card-header"><div><h2>Emergency checklist</h2><p>Prepare before conditions worsen</p></div><span class="tag low">Recommended</span></div><div class="three-col">${[['Emergency kit','Water, medicines, torch, radio and first-aid supplies.'],['Family plan','Choose a meeting point and keep key numbers offline.'],['Official updates','Use verified district alerts; do not share unverified rumours.']].map(x=>`<div class="insight"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div></section><div class="alert-strip" style="margin-top:16px;border-left-color:#da4b50;background:#fff7f7;border-color:#f0d0d1"><span class="alert-symbol" style="color:#b33f46;background:#ffe5e6">${icon('phone')}</span><div class="alert-strip-content"><strong style="color:#a23e44">Immediate danger?</strong><p>Call 112. Follow official evacuation instructions and help children, older adults and people with disabilities move safely.</p></div><button class="btn btn-danger btn-sm" data-action="contacts">Emergency contacts</button></div>`;}

