const baseRender = render;
render = function(){
  let content='';
  switch(state.view){
    case 'landslide': content=predictionView('landslide'); break;
    case 'flood': content=predictionView('flood'); break;
    case 'rainfall': content=rainfallAnalyticsView(); break;
    case 'soil-moisture': content=soilMoistureAnalyticsView(); break;
    case 'terrain': content=terrainView(); break;
    case 'explainability': content=explainabilityView(); break;
    case 'reports': content=reportsView(); break;
    case 'sensors': content=sensorManagementView(); break;
    case 'users': content=usersView(); break;
    case 'audit': content=auditView(); break;
    case 'safety': content=safetyView(); break;
    default: return baseRender();
  }
  document.getElementById('app').innerHTML=shell(content)+overlayHTML();
  const timeEl=document.getElementById('topbar-time');
  if(timeEl) timeEl.textContent=state.updated.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
};
render();

document.addEventListener('keydown', event => {
  if (event.key !== 'Enter' || event.target.id !== 'global-search') return;
  const query = event.target.value.trim().toLowerCase();
  const match = villages.find(v => `${v.name} ${v.area}`.toLowerCase().includes(query));
  if (match) { state.location = match; state.drawer = match; state.modal = null; render(); }
  else if (query) toast('No location found', 'Try a village name such as Karsog, Thunag or Janjehli.');
});
document.addEventListener('input', event => {
  if (event.target.id !== 'location-search') return;
  const query = event.target.value.trim().toLowerCase();
  document.querySelectorAll('[data-location-select]').forEach(row => {
    row.hidden = query && !row.textContent.toLowerCase().includes(query);
  });
});

function downloadCsv(filename, rows) {
  const csv = rows.map(row => row.map(value => `"${String(value).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], {type:'text/csv;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a'); link.href=url; link.download=filename; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
async function syncApiHealth() {
  const pill = document.querySelector('.system-pill');
  try {
    const response = await fetch('/api/health');
    if (!response.ok) throw new Error('API unavailable');
    const payload = await response.json();
    if (pill && payload.data?.status === 'operational') pill.innerHTML = '<span class="dot"></span>API connected';
  } catch {
    if (pill) pill.innerHTML = '<span class="dot amber"></span>Demo mode';
  }
}
syncApiHealth();
